<!--
 * 任务 Webhook（列表页）
 *
 * @path apps\cronjob-web\src\views\webhook\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务 Webhook（列表页）
 * <p>消费后端契约 JobWebhookController（src/api/jobWebhook.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页加载；支持新增（webhook-form.vue）、编辑、状态切换（启/停）、测试推送 testWebhook()、删除 deleteApi()。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButtonBase } from '@ydsz-core/ydsz-ui';
import { h } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { deleteApi, page, testWebhook, update } from '#/api/jobWebhook';
import type { JobWebhookVO } from '#/api/models';

import WebhookForm from './webhook-form.vue';

defineOptions({ name: 'WebhookManagement' });
const { t } = useI18n();

const webhookGridOptions: VxeGridProps<JobWebhookVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'name', title: t('business.webhookName'), width: 160 },
    { field: 'eventType', title: t('business.webhookEventType'), width: 150 },
    { field: 'jobKey', title: t('business.webhookJobKey'), width: 140 },
    { field: 'callbackUrl', title: t('business.webhookCallbackUrl'), width: 220 },
    { field: 'httpMethod', title: 'HTTP Method', width: 110 },
    {
      field: 'webhookStatus',
      title: t('common.status'),
      width: 90,
      slots: {
        default: ({ row }) => {
          const item = row as JobWebhookVO;
          return h(
            YdBadge,
            { variant: item.webhookStatus === 'ACTIVE' ? 'default' : 'secondary' },
            () => (item.webhookStatus === 'ACTIVE' ? t('common.enabled') : t('common.disabled')),
          );
        },
      },
    },
    { field: 'createdAt', title: t('common.createTime'), width: 160 },
    {
      field: 'action',
      title: t('common.actions'),
      width: 280,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const item = row as JobWebhookVO;
          return h('div', { class: 'flex gap-1' }, [
            h(YdButtonBase, { size: 'sm', variant: 'link', onClick: () => handleEdit(item) }, () => t('common.edit')),
            h(YdButtonBase, { size: 'sm', variant: 'link', onClick: () => handleToggle(item) }, () => (item.webhookStatus === 'ACTIVE' ? '停用' : '启用')),
            h(YdButtonBase, { size: 'sm', variant: 'link', onClick: () => handleTest(item) }, () => t('business.webhookTest')),
            h(YdButtonBase, { size: 'sm', variant: 'link', onClick: () => handleDelete(item) }, () => t('common.delete')),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ formData }: { formData: Record<string, unknown> }) => {
        const res = await page({
          pageNum: (formData?.pageNum as number) || 1,
          size: (formData?.size as number) || 20,
          eventType: formData?.eventType as string,
          jobKey: formData?.jobKey as string,
        });
        return { items: res?.data ?? [], total: res?.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions: webhookGridOptions });

const [WebhookFormModal, webhookFormApi] = useYdModal({ connectedComponent: WebhookForm });

function handleAdd() {
  webhookFormApi.open();
}

function handleEdit(row: JobWebhookVO) {
  webhookFormApi.setData({ record: row });
  webhookFormApi.open();
}

async function handleToggle(row: JobWebhookVO) {
  if (!row.id) return;
  const nextStatus = row.webhookStatus === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE';
  try {
    await update({ ...row, webhookStatus: nextStatus });
    showToast.success(nextStatus === 'ACTIVE' ? '已启用' : '已停用');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleTest(row: JobWebhookVO) {
  if (!row.id) return;
  try {
    await testWebhook({ id: row.id });
    showToast.success('测试推送成功');
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleDelete(row: JobWebhookVO) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(
      `${t('business.webhookConfirmDelete')}「${row.name}」？`,
      t('common.crud.deleteConfirmTitle'),
      { type: 'warning' },
    );
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    if (row.id) await deleteApi({ id: row.id });
    showToast.success(t('common.crud.deleteSuccess'));
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('page.webhook')">
      <template #toolbar-tools>
        <YdButtonBase @click="handleAdd">{{ t('common.create') }}</YdButtonBase>
      </template>
    </Grid>
    <WebhookFormModal @success="gridApi.query()" />
  </Page>
</template>
